import gzip,re,collections
f='axolotl.gtf.gz'
g={}
with gzip.open(f,'rt') as h:
 for line in h:
  if '\\tgene\\t' not in line: continue
  a=line.rstrip('\\n').split('\\t'); attrs=a[8]
  gd=dict(re.findall(r'(\\w+) \"(["'^"]*)"'"',attrs))
  names=[]
  for n in gd.get('gene_name','').split('|'):
   n=re.sub(r'\\s*\\[(?:hs|nr)\\]','',n).strip()
   if n: names.append(n)
  for n in names:
   g.setdefault(n.upper(),[]).append((a[0],int(a[3]),int(a[4]),a[6],gd.get('gene_id')))
